using Health_Care_System.BLL.Interfaces; using Health_Care_System.BLL.Models; using Health_Care_System.Entities;
namespace Health_Care_System.BLL.Services;
public sealed class PatientService:IPatientService { private readonly IUnitOfWork _uow; public PatientService(IUnitOfWork uow)=>_uow=uow; private IGenericRepository<Patient> Repo=>_uow.Patients; public async Task<Result<PaginatedList<Patient>>> GetAllAsync(string? searchValue,int pageIndex,int pageSize){var data=string.IsNullOrWhiteSpace(searchValue)?await Repo.GetAllAsync():await Repo.SearchAsync(searchValue);return Result<PaginatedList<Patient>>.Success(PaginatedList<Patient>.Create(data,pageIndex,pageSize));} public async Task<Result<Patient>> GetByIdAsync(int id){var item=await Repo.GetAsync(id);return item is null?Result<Patient>.Failure("Patient not found."):Result<Patient>.Success(item);} public async Task<Result<Patient>> CreateAsync(Patient entity){await Repo.CreateAsync(entity);await _uow.SaveChangesAsync();return Result<Patient>.Success(entity);} public async Task<Result<Patient>> UpdateAsync(Patient entity){var existing=await Repo.GetAsync(entity.Id);if(existing is null)return Result<Patient>.Failure("Patient not found."); Copy(entity,existing);Repo.Update(existing);await _uow.SaveChangesAsync();return Result<Patient>.Success(existing);} public async Task<Result<Patient>> DeleteAsync(int id){var item=await Repo.GetAsync(id);if(item is null)return Result<Patient>.Failure("Patient not found.");Repo.Delete(item);await _uow.SaveChangesAsync();return Result<Patient>.Success(item);} private static void Copy(Patient source,Patient target){target.Name=source.Name;target.BirthDate=source.BirthDate;}} 
